  a0 = Z_to_bv 64 S -> a1 = Z_to_bv 64 l -> a2 = Z_to_bv 64 Fp ->
  (0 < wend < 2^64) -> (0 <= wpos) -> (l <= wend - wpos) -> (S < 2^64) ->
  (2^31 <= lbf < 2^32) ->
  stk asegs m lo (bv_unsigned sp) -> (lo <= bv_unsigned sp - 2304) -> (0 <= lo) -> (bv_unsigned sp < 2^63) ->
  mem_inv asegs m ->
