  (wend <= lo \/ bv_unsigned sp <= wpos) -> (wend <= Fp \/ Fp + 232 <= wpos) ->
  (S + l <= wpos \/ wend <= S) -> (S + l <= lo \/ bv_unsigned sp <= S) -> (S + l <= Fp \/ Fp + 232 <= S) ->
  kHighShadowEnd + 8 <= lo -> chkr m S l -> chkr m wpos (Z.of_nat cap) -> ictx m ->     (* [comment removed for export] *)
